### 4. Fondu des nouvelles lettres et shadow de glyphe dans `board()`

Dans la boucle d’interpolation de `board()`, remplacer le bloc `if(old&&...)` par :

```c
int glyph_reveal = (f->kind == 3 && p->chroma == 2 &&
                    f->transition < 1.0f &&
                    (!old || old->texture != p->texture));

if (glyph_reveal) {
    p->alpha = (unsigned)lroundf(256.0f * e);
    p->y += (1.0f - e) * 12.0f;
} else if (old && f->transition < 1) {
    p->x = old->x + (p->x - old->x) * e;
    p->y = old->y + (p->y - old->y) * e;
    if (f->kind == 0 && old->texture != p->texture) {
        float shrink = fabsf(cosf(3.14159265f * f->transition));
        p->x += p->w * (1 - shrink) / 2;
        p->w *= shrink;
        if (f->transition < .5f) p->texture = old->texture;
    }
} else if (!old && f->old_n && f->transition < 1) {
    p->alpha = 64 + 192 * e;
    p->y += (1 - e) * 12;
}
```

Dans la passe shadow existante, ne pas appliquer la tuile 55 aux glyphes :

```c
if (!pass) {
    if (p.texture == 56 || p.chroma >= 2) continue;
    p.x += 3; p.y += 5; p.texture = 55; p.chroma = 0;
    if (!textured(r,&p,scale,90)) return 0;
} else {
    if (p.chroma == 2 && p.texture != 26u) {
        L3FestivalPose sh = p;
        sh.chroma = 3;
        sh.x += 2.0f;
        sh.y += 3.0f;
        sh.alpha = (unsigned)((p.alpha * 72u) / 256u);
        if (!textured(r,&sh,scale,sh.alpha)) return 0;
    }
    if (!textured(r,&p,scale,(unsigned)p.alpha)) return 0;
}
```

Ainsi :
- lettre invisible ⇒ `p.alpha=0` ⇒ shadow alpha 0 ;
- lettre à 50 % ⇒ shadow à environ 14 % ;
- shadow jamais opaque ;
- underscore sans shadow (`texture==26u`).

---

### 5. Retirer le mot UI dupliqué dans `overlay()`

Dans `overlay()`, branche `if(f->kind==3)`, supprimer tout le bloc :

```c
char word[72]; ... ui_text(r,f,x,(int)h/2,word,78,w/2);
```

Ne garder que :

```c
char letters[80];
unsigned at = 0;
for (unsigned i = 0; i < 26; ++i) {
    letters[at++] = f->view.data.hangman.guessed[i] ? '.' : (char)('A'+i);
    letters[at++] = ' ';
}
letters[at] = 0;
ui_text(r,f,w/5,h*2/3,letters,74,w*3/5);
ui_text(r,f,60,h/2-40,f->view.hint,74,w-120);
```

Le statut, l’alphabet et le hint restent inchangés. Aucune modification de `act()`, de `l3_table_*`, de `l3_festival_save/load` ni de `l3_festival.h`.

